import{_ as r,c as e,o as l,a1 as o}from"./chunks/framework.C3Hmo1as.js";const g=JSON.parse('{"title":"MACD","description":"一些零碎的知识","frontmatter":{"title":"MACD","description":"一些零碎的知识","date":"2026-08-07T00:00:00.000Z","tags":[],"outline":[2,3]},"headers":[],"relativePath":"trader/macd.md","filePath":"trader/macd.md"}'),t={name:"trader/macd.md"};function i(n,a,s,d,A,h){return l(),e("div",null,[...a[0]||(a[0]=[o('<h2 id="概念" tabindex="-1">概念 <a class="header-anchor" href="#概念" aria-label="Permalink to &quot;概念&quot;">​</a></h2><h3 id="macd-是什么" tabindex="-1">MACD 是什么 <a class="header-anchor" href="#macd-是什么" aria-label="Permalink to &quot;MACD 是什么&quot;">​</a></h3><ul><li>MACD 全称为 <code>指数平滑异同移动平均线</code> (Moving Average Convergence Divergence)，由技术分析师 Gerald Appel 于 1970 年代末提出。它本质上是一个<code>趋势跟踪</code>的<code>动量指标</code></li><li>通过比较两根不同周期的<code>指数移动平均线</code> (EMA) 的差值，来衡量市场价格运行的动能强弱，并捕捉可能的<code>趋势反转点</code>。</li><li>它的核心是教大家<strong>判断买卖时机</strong>。</li></ul><h3 id="macd-的适用性" tabindex="-1">MACD 的适用性 <a class="header-anchor" href="#macd-的适用性" aria-label="Permalink to &quot;MACD 的适用性&quot;">​</a></h3><p>MACD 并不是 A 股市场特有的指标，而是<strong>全球金融市场最基础、最通用的技术分析指标之一</strong>。无论是美股、欧洲股市、外汇市场，还是大宗商品和加密货币交易，MACD 都被广泛作为研判趋势和动能的核心工具。</p><hr><h3 id="ema-指数移动平均线" tabindex="-1">EMA - 指数移动平均线 <a class="header-anchor" href="#ema-指数移动平均线" aria-label="Permalink to &quot;EMA - 指数移动平均线&quot;">​</a></h3><ul><li>指数移动平均线（Exponential Moving Average，简称 EMA），是一种对时间序列数据（如股票价格）进行平滑处理的统计方法。</li><li>EMA 是一种加权移动平均线，它对时间序列中的每个数据点赋予不同的权重。最新数据被赋予最大权重，且越久远的数据权重呈指数级递减，但理论上永远不会衰减为零。</li><li>与简单移动平均线（SMA）在固定窗口期内对所有数据“一视同仁”不同，EMA 通过指数衰减的权重分配机制，使得计算结果对最新价格变化更加敏感。</li></ul><h3 id="平滑" tabindex="-1">平滑 <a class="header-anchor" href="#平滑" aria-label="Permalink to &quot;平滑&quot;">​</a></h3><ul><li>平滑处理，是指通过特定的数学算法（如求平均值），滤除时间序列数据中的“短期随机波动（噪音）”，从而提取并凸显出数据背后“长期、真实的内在趋势（信号）”的过程。</li><li>在视觉表现上，就是把一条剧烈上下震荡、充满毛刺的锯齿状折线，变成一条相对平缓、圆滑、拐点较少的曲线。</li></ul><hr><h2 id="相关概念" tabindex="-1">相关概念 <a class="header-anchor" href="#相关概念" aria-label="Permalink to &quot;相关概念&quot;">​</a></h2><h3 id="macd-line-也叫-dif-快线" tabindex="-1">MACD line - 也叫 DIF / 快线 <a class="header-anchor" href="#macd-line-也叫-dif-快线" aria-label="Permalink to &quot;MACD line - 也叫 DIF / 快线&quot;">​</a></h3><h3 id="signal-也叫-dea-慢线" tabindex="-1">Signal - 也叫 DEA / 慢线 <a class="header-anchor" href="#signal-也叫-dea-慢线" aria-label="Permalink to &quot;Signal - 也叫 DEA / 慢线&quot;">​</a></h3><h3 id="能量柱-快线减去慢线" tabindex="-1">能量柱 - 快线减去慢线 <a class="header-anchor" href="#能量柱-快线减去慢线" aria-label="Permalink to &quot;能量柱 - 快线减去慢线&quot;">​</a></h3><h3 id="零轴-零轴的上方大于零-零轴的下方都是小于零" tabindex="-1">零轴 - 零轴的上方大于零，零轴的下方都是小于零 <a class="header-anchor" href="#零轴-零轴的上方大于零-零轴的下方都是小于零" aria-label="Permalink to &quot;零轴 - 零轴的上方大于零，零轴的下方都是小于零&quot;">​</a></h3><h3 id="一、-macd-是什么-全球通用定义" tabindex="-1">一、 MACD 是什么？（全球通用定义） <a class="header-anchor" href="#一、-macd-是什么-全球通用定义" aria-label="Permalink to &quot;一、 MACD 是什么？（全球通用定义）&quot;">​</a></h3><p>MACD 的全称是 <strong>Moving Average Convergence Divergence（指数平滑异同移动平均线）</strong>，由美国人 Gerald Appel 于 1979 年发明。它的核心逻辑是通过研究<strong>短期和长期移动平均线之间的聚合与分离状况</strong>，来判断买卖时机。</p><p>它主要由三个部分组成（默认参数通常为 12, 26, 9）：</p><ol><li><strong>DIF（快线）：</strong> 短期 EMA（12日）减去长期 EMA（26日）。代表短期价格动能。</li><li><strong>DEA（慢线）：</strong> DIF 的 9日 EMA。是快线的平滑线，用来发出更稳定的信号。</li><li><strong>MACD 柱状图（红绿柱）：</strong> (DIF - DEA) × 2。用红绿柱的长短来直观显示多空力量的强弱变化。</li></ol><hr><h3 id="二、-为什么说-macd-不是-a-股特有" tabindex="-1">二、 为什么说 MACD 不是 A 股特有？ <a class="header-anchor" href="#二、-为什么说-macd-不是-a-股特有" aria-label="Permalink to &quot;二、 为什么说 MACD 不是 A 股特有？&quot;">​</a></h3><p>MACD 是一个纯粹的数学统计模型，只要是有价格和时间序列的市场，它就能用。</p><ul><li><strong>在美股/外汇市场：</strong> 交易员用它来判断长期趋势的转折、结合其他指标（如 RSI、布林带）做量化模型。</li><li><strong>在全球加密货币市场：</strong> 因为 24 小时交易且波动极大，MACD 的“金叉/死叉”常被高频交易者和量化机器人用来捕捉短期动量。</li></ul><hr><h3 id="三、-macd-在-a-股市场的-特色策略-与行话" tabindex="-1">三、 MACD 在 A 股市场的“特色策略”与行话 <a class="header-anchor" href="#三、-macd-在-a-股市场的-特色策略-与行话" aria-label="Permalink to &quot;三、 MACD 在 A 股市场的“特色策略”与行话&quot;">​</a></h3><p>虽然指标是全球的，但 <strong>A 股市场的参与者结构（散户多、情绪化重）和交易制度（T+1、涨跌停）</strong>，让 MACD 在 A 股演化出了一套特有的实战体系和“黑话”：</p><h4 id="_1-水上-与-水下-a-股特有行话" tabindex="-1">1. “水上”与“水下”（A 股特有行话） <a class="header-anchor" href="#_1-水上-与-水下-a-股特有行话" aria-label="Permalink to &quot;1. “水上”与“水下”（A 股特有行话）&quot;">​</a></h4><p>在 A 股论坛（如雪球、淘股吧），老股民很少说“零轴上方/下方”，而是称之为 <strong>“水上”</strong> 和 <strong>“水下”</strong>。</p><ul><li><strong>零轴（0轴）：</strong> 被视为 A 股的多空分水岭（牛熊线）。</li><li><strong>水上（DIF 和 DEA 均大于 0）：</strong> 代表股票处于多头主导的强势区。A 股策略通常强调“只做水上金叉”，认为水上的回调是洗盘，安全性高。</li><li><strong>水下（DIF 和 DEA 均小于 0）：</strong> 代表空头主导的弱势区。A 股有句俗话叫“水下金叉多为反弹，水上死叉多为洗盘”。</li></ul><h4 id="_2-背离-策略-a-股散户的-圣杯" tabindex="-1">2. “背离”策略（A 股散户的“圣杯”） <a class="header-anchor" href="#_2-背离-策略-a-股散户的-圣杯" aria-label="Permalink to &quot;2. “背离”策略（A 股散户的“圣杯”）&quot;">​</a></h4><p>在成熟市场，交易员可能更看重趋势跟踪；但在 A 股，由于“牛短熊长”和频繁的“割韭菜”行情，A 股投资者极其痴迷于用 MACD 抓 <strong>“背离（Divergence）”</strong> 来抄底和逃顶。</p><ul><li><strong>底背离抄底：</strong> 股价创出新低，但 MACD 的绿柱子却在缩短，或者 DIF 线没有创新低。A 股资金常以此作为主力“诱空”结束、准备拉升的强烈买入信号。</li><li><strong>顶背离逃顶：</strong> 股价创新高，但 MACD 红柱缩短或 DIF 没创新高。在 A股，这通常被视为庄家出货、动能衰竭的标志，是极强的卖出信号。</li></ul><h4 id="_3-结合-做-t-策略-应对-t-1-制度" tabindex="-1">3. 结合“做 T”策略（应对 T+1 制度） <a class="header-anchor" href="#_3-结合-做-t-策略-应对-t-1-制度" aria-label="Permalink to &quot;3. 结合“做 T”策略（应对 T+1 制度）&quot;">​</a></h4><p>A 股实行 T+1（今天买的股票明天才能卖），无法像美股那样日内随意止损。因此，A 股股民发明了利用 MACD 分时图（如 15 分钟、30 分钟级别）来 <strong>“做 T”（日内 T+0 滚动操作）</strong> 的策略：</p><ul><li><strong>正 T（先买后卖）：</strong> 早盘 30 分钟 MACD 出现底背离或水下金叉，用底仓或现金买入；等盘中冲高，分时 MACD 出现顶背离或死叉时，将原有底仓卖出，赚取日内差价，降低持仓成本。</li><li><strong>倒 T（先卖后买）：</strong> 早盘冲高时，分时 MACD 出现顶背离，先卖出底仓；等下午跳水，分时 MACD 死叉或绿柱放大时再接回。</li></ul><h4 id="_4-红绿柱-的面积与缩量" tabindex="-1">4. “红绿柱”的面积与缩量 <a class="header-anchor" href="#_4-红绿柱-的面积与缩量" aria-label="Permalink to &quot;4. “红绿柱”的面积与缩量&quot;">​</a></h4><p>A 股技术分析流派中，有一种专门看 MACD 柱子“面积”的流派。</p><ul><li><strong>抽脚/缩头：</strong> 绿柱开始变短叫“抽脚”（可能止跌），红柱开始变短叫“缩头”（可能见顶）。</li><li><strong>拒绝死叉（空中加油）：</strong> 在 A 股的主升浪妖股中，DIF 线向下靠近 DEA 线，眼看要死叉，但突然股价再次放量拉升，DIF 重新拐头向上。这在 A 股被称为“空中加油”或“老鸭头”形态，是极强的追涨信号。</li></ul><hr><h3 id="四、-macd-在-a-股的致命缺陷-为什么很多人亏钱" tabindex="-1">四、 MACD 在 A 股的致命缺陷（为什么很多人亏钱？） <a class="header-anchor" href="#四、-macd-在-a-股的致命缺陷-为什么很多人亏钱" aria-label="Permalink to &quot;四、 MACD 在 A 股的致命缺陷（为什么很多人亏钱？）&quot;">​</a></h3><p>尽管 MACD 在 A 股被奉为圭臬，但它有一个全球通用的致命弱点，而在 A 股尤为明显：<strong>滞后性与震荡市的“左右打脸”</strong>。</p><ol><li><strong>指标滞后：</strong> MACD 是基于移动平均线计算的，而均线本身就是滞后的。当 A 股出现突发利好（如政策出台）导致股票“一字涨停”时，MACD 根本来不及反应；等 MACD 发出金叉买入信号时，往往已经连拉了几个涨停板，处于高位接盘的危险区。</li><li><strong>震荡市“骗线”：</strong> A 股有 70% 的时间处于无趋势的横盘震荡期。在震荡市中，MACD 会频繁发出金叉和死叉信号。如果你机械地按照“金叉买、死叉卖”，在 A 股会被反复“两面打耳光”，本金很快就会被手续费和微小的亏损磨损殆尽（俗称“钝化”）。</li></ol><h3 id="总结" tabindex="-1">总结 <a class="header-anchor" href="#总结" aria-label="Permalink to &quot;总结&quot;">​</a></h3><ul><li><strong>MACD 的本质：</strong> 它是全球通用的“趋势与动量”温度计，绝不是 A 股特产。</li><li><strong>A 股的正确打开方式：</strong> 在 A 股，单纯看 MACD 的“金叉/死叉”胜率极低。真正的高手通常将其作为<strong>辅助验证工具</strong>： <ol><li><strong>结合成交量（量价配合）：</strong> 无量金叉多为耍流氓。</li><li><strong>结合大盘情绪与题材：</strong> A 股是政策市和情绪市，题材风口上的猪，MACD 水下死叉也能涨；退潮期的龙头，MACD 水上金叉也会跌停。</li><li><strong>大周期制约小周期：</strong> 周线 MACD 向下的股票，日线级别的 MACD 金叉通常只能视为反弹，不能重仓。</li></ol></li></ul>',45)])])}const D=r(t,[["render",i]]);export{g as __pageData,D as default};
